import ShellTesting
import Darwin

/// The od command is the hexdump program run under the name "od".
///
/// The tests run it through a symbolic link called "od" that points at the hexdump built next to the
/// test bundle (which is how Xcode runs them).  Without that bundle path the system od is used instead.
@Suite("od tests", .serialized) final class odTest : ShellTest {
  let cmd : String
  let suiteBundle = "shell_cmds_hexdumpTest"

  static let odLink : String = {
    guard let bundle = Environment["XCTestBundlePath"] else {
      return "od"
    }
    let hexdump = FilePath(bundle).removingLastComponent().appending("hexdump")
    let dir = FilePath(Environment["TMPDIR"] ?? "/tmp").appending("hexdump_od_\(getpid())")
    try? dir.removeTree()
    try? dir.createDirectory(FilePermissions(rawValue: 0o755))
    let link = dir.appending("od")
    try? link.createSymbolicLink(to: hexdump)
    return link.string
  }()

  init() {
    cmd = Self.odLink
  }

