  @Test("od output matches the system od in a UTF-8 locale", arguments: utf8Cases)
  func matchesSystemOdInUTF8(_ args: [String], _ stdinFile: String?, _ expected: [UInt8], _ status: Int) async throws {
    let dir = HexdumpFixture.dir
    var stdin: [UInt8]? = nil
    if let stdinFile {
      stdin = try dir.appending(stdinFile).readAllBytes()
    }
    try await run(withStdin: stdin, status: status, output: expected, args: args, env: ["LC_ALL": "en_US.UTF-8"], cd: dir)
  }
}
